Unit Test Code:
#include "unity.h"
#include "buffer.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_buffer_append_n_resize_failure(void) {
    // Setup: create a buffer with small content and size
    buffer_t *buf = helper_create_buffer_with_content("abc");
    TEST_ASSERT_NOT_NULL(buf);

    // The buffer's current content is "abc" (length 3)
    // Let's try to append "XYZ" (len=3), so needed = 3+3=6
    // We want to force buffer_resize to fail when called

    // The buffer was created with size = strlen("abc") = 3
    // So self->len == 3, which is NOT > needed (6), so resize will be attempted

    // There are 2 allocations in setup (helper_create_buffer_with_content):
    //   - buffer_new_with_copy("abc") calls buffer_new_with_size(3): 2 allocations
    // To fail the next allocation (the realloc in buffer_resize), use malloc_fail_after(2)
    malloc_fail_after(2);

    int ret = buffer_append_n(buf, "XYZ", 3);
    TEST_ASSERT_EQUAL_INT(-1, ret);

    // The buffer should remain unchanged
    helper_assert_buffer_equals(buf, "abc");
    helper_assert_buffer_length(buf, 3);

    // Cleanup
    helper_free_buffer(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_append_n_resize_failure);
    return UNITY_END();
}

